using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;

namespace IntegratedErp.BuildingBlocks.Storage;

/// <summary>
/// Object storage with S3 semantics (docs/02-target-architecture/14 §1): flat keys, whole-object put/get.
/// On company servers it is a folder; MinIO or cloud blob storage plug in behind the same interface later.
/// Keys are generated by the system (never from user input) and contain only [a-z0-9/-].
/// </summary>
public interface IFileStorage
{
    Task PutAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Null when the object does not exist.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    Task DeleteAsync(string key, CancellationToken cancellationToken);
}

public sealed class StorageOptions
{
    public const string Section = "Storage";

    /// <summary>Folder for the file-system provider; default <c>%LOCALAPPDATA%\IntegratedErp\files</c>.</summary>
    public string? Root { get; set; }
}

/// <summary>Stores each object as a file under <see cref="StorageOptions.Root"/>. Writes go to a temp file first, then move.</summary>
public sealed class FileSystemStorage : IFileStorage
{
    private readonly string _root;

    public FileSystemStorage(IOptions<StorageOptions> options)
    {
        ArgumentNullException.ThrowIfNull(options);
        _root = Path.GetFullPath(options.Value.Root is { Length: > 0 } configured
            ? configured
            : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "IntegratedErp", "files"));
        Directory.CreateDirectory(_root);
    }

    public async Task PutAsync(string key, Stream content, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(content);
        var path = PathOf(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var temp = path + ".uploading";
        await using (var file = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true))
        {
            await content.CopyToAsync(file, cancellationToken).ConfigureAwait(false);
        }

        File.Move(temp, path, overwrite: false);
    }

    public Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken)
    {
        var path = PathOf(key);
        return Task.FromResult<Stream?>(File.Exists(path)
            ? new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true)
            : null);
    }

    public Task DeleteAsync(string key, CancellationToken cancellationToken)
    {
        File.Delete(PathOf(key));
        return Task.CompletedTask;
    }

    /// <summary>Refuses anything that is not a plain system key, so a key can never leave the root folder.</summary>
    private string PathOf(string key)
    {
        if (string.IsNullOrEmpty(key) || key.Length > 300 || key.StartsWith('/') || key.Contains("..", StringComparison.Ordinal)
            || !key.All(c => c is (>= 'a' and <= 'z') or (>= '0' and <= '9') or '/' or '-'))
        {
            throw new ArgumentException("Invalid storage key.", nameof(key));
        }

        var path = Path.GetFullPath(Path.Combine(_root, key.Replace('/', Path.DirectorySeparatorChar)));
        if (!path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException("Invalid storage key.", nameof(key));
        }

        return path;
    }
}

public static class StorageExtensions
{
    public static IServiceCollection AddFileStorage(this IServiceCollection services, IConfiguration configuration)
    {
        services.AddOptions<StorageOptions>().Bind(configuration.GetSection(StorageOptions.Section));
        services.AddSingleton<IFileStorage, FileSystemStorage>();
        return services;
    }
}
